select id, type, name, sort, status, create_time, update_time, create_user, update_user from category where status = 1
and type = #{type}
order by sort asc,update_time desc

select id, type, name, sort, status, create_time, update_time, create_user, update_user
from category


        and name like concat('%',#{name},'%')


        and type = #{type}


        and status = #{status}


order by sort asc , update_time desc
